"""Generate and install static bash completion scripts for dotfig."""

from __future__ import annotations

import os
import re
import shlex
import shutil
import subprocess  # ruff: ignore[suspicious-subprocess-import]
import tempfile
from dataclasses import dataclass
from importlib.metadata import version as package_version
from pathlib import Path
from typing import Literal

import click

APP_NAME = "dotfig"
BASH_MINIMUM = (4, 4)
_GENERATED_NOTICE = (
    "# Generated by `dotfig --completions`; do not edit. "
    "Rerun the command to regenerate."
)
_KIND = Literal["none", "files", "dirs", "choices"]


@dataclass(frozen=True)
class _Value:
    """How to complete one value of a Click parameter."""

    kind: _KIND
    choices: tuple[str, ...] = ()


@dataclass(frozen=True)
class _Option:
    """A Click option and the values it takes."""

    names: tuple[str, ...]
    values: tuple[_Value, ...]


def _quote(value: str) -> str:
    return shlex.quote(value)


def _sanitize(name: str) -> str:
    return re.sub(r"[^A-Za-z0-9_]", "_", name)


def _value_for_type(param_type: click.ParamType[object]) -> _Value:
    if isinstance(param_type, click.Choice):
        return _Value(
            "choices", tuple(str(choice) for choice in param_type.choices)
        )
    if isinstance(param_type, click.Path):
        return _Value("dirs" if param_type.file_okay is False else "files")
    if isinstance(param_type, click.File):
        return _Value("files")
    return _Value("none")


def _option_values(option: click.Option) -> tuple[_Value, ...]:
    if isinstance(option.type, click.Tuple):
        return tuple(_value_for_type(item) for item in option.type.types)
    nargs = option.nargs
    if nargs <= 0:
        return (_value_for_type(option.type),)
    return (_value_for_type(option.type),) * nargs


def _help_names(command: click.Command) -> tuple[str, ...]:
    if getattr(command, "add_help_option", True) is False:
        return ()
    names = command.context_settings.get("help_option_names", ["--help"])
    return tuple(str(name) for name in names)


def _options(
    command: click.Command,
) -> tuple[tuple[str, ...], tuple[_Option, ...]]:
    """Split COMMAND's options into flags and value-taking options.

    Returns:
        A pair of flag names and value-taking options.

    """
    flags = list(_help_names(command))
    values: list[_Option] = []
    for param in command.params:
        if not isinstance(param, click.Option):
            continue
        if getattr(param, "hidden", False):
            continue
        names = (*param.opts, *param.secondary_opts)
        if param.is_flag or param.count:
            flags.extend(names)
            continue
        values.append(_Option(tuple(names), _option_values(param)))
    return tuple(flags), tuple(values)


def _argument_values(argument: click.Argument) -> tuple[_Value, ...]:
    if isinstance(argument.type, click.Tuple):
        return tuple(_value_for_type(item) for item in argument.type.types)
    nargs = argument.nargs
    if nargs <= 0:
        return (_value_for_type(argument.type),)
    return (_value_for_type(argument.type),) * nargs


def _positional_slots(
    command: click.Command,
) -> tuple[list[_Value], _Value | None, int]:
    """Return fixed slots and the variadic tail for COMMAND's arguments.

    Returns:
        The fixed value slots, the variadic value, and its start index.

    """
    slots: list[_Value] = []
    variadic: _Value | None = None
    variadic_start = 0
    for param in command.params:
        if not isinstance(param, click.Argument):
            continue
        if getattr(param, "hidden", False):
            continue
        values = _argument_values(param)
        if param.nargs == -1:
            variadic = values[-1]
            variadic_start = len(slots)
            break
        slots.extend(values)
    return slots, variadic, variadic_start


def _completion_snippet(
    value: _Value, *, indent: str, prefix: str
) -> list[str]:
    if value.kind == "choices":
        choices = " ".join(_quote(choice) for choice in value.choices)
        suffix = f" {choices}" if choices else ""
        return [f'{indent}{prefix}_offer "$cur"{suffix}']
    if value.kind == "files":
        return [f"{indent}{prefix}_files"]
    if value.kind == "dirs":
        return [f"{indent}{prefix}_dirs"]
    return []


def _prefixed_snippet(value: _Value, *, indent: str, prefix: str) -> list[str]:
    terminator = [f"{indent}return", f"{indent};;"]
    if value.kind == "choices":
        choices = " ".join(_quote(choice) for choice in value.choices)
        suffix = f" {choices}" if choices else ""
        return [
            f'{indent}{prefix}_offer_prefixed "$cur"{suffix}',
            *terminator,
        ]
    if value.kind == "files":
        return [f'{indent}{prefix}_files_prefixed "$cur"', *terminator]
    if value.kind == "dirs":
        return [f'{indent}{prefix}_dirs_prefixed "$cur"', *terminator]
    return terminator


def _value_case(
    name: str, values: tuple[_Value, ...], *, indent: str, prefix: str
) -> list[str]:
    lines = [f"{indent}{_quote(name)})"]
    if len(values) == 1:
        lines.extend(
            _completion_snippet(
                values[0], indent=indent + "    ", prefix=prefix
            )
        )
    else:
        lines.append(f"{indent}    case $last_count in")
        for index, value in enumerate(values):
            lines.append(f"{indent}        {index})")
            lines.extend(
                _completion_snippet(
                    value, indent=indent + "            ", prefix=prefix
                )
            )
            lines.append(f"{indent}            ;;")
        lines.append(f"{indent}        *)")
        lines.extend(
            _completion_snippet(
                values[-1], indent=indent + "            ", prefix=prefix
            )
        )
        lines.extend([f"{indent}            ;;", f"{indent}    esac"])
    lines.extend([f"{indent}    return", f"{indent}    ;;"])
    return lines


def _option_cases(
    values: tuple[_Option, ...], flags: tuple[str, ...], *, indent: str
) -> list[str]:
    lines = [
        f"{indent}--)",
        f"{indent}    opts_done=1",
        f'{indent}    last_opt=""',
        f"{indent}    ;;",
    ]
    for name in flags:
        lines.extend(
            [
                f"{indent}{_quote(name)})",
                f'{indent}    last_opt=""',
                f"{indent}    ;;",
            ]
        )
    for option in values:
        for name in option.names:
            if name.startswith("--"):
                lines.extend(
                    [
                        f"{indent}{_quote(name)}=*)",
                        f'{indent}    last_opt=""',
                        f"{indent}    ;;",
                    ]
                )
        for name in option.names:
            lines.extend(
                [
                    f"{indent}{_quote(name)})",
                    f"{indent}    last_opt={_quote(name)}",
                    f"{indent}    last_count=0",
                    f"{indent}    last_max={len(option.values)}",
                    f"{indent}    ;;",
                ]
            )
    lines.extend(
        [
            f"{indent}-*)",
            f'{indent}    last_opt=""',
            f"{indent}    ;;",
        ]
    )
    return lines


def _parse_body(
    values: tuple[_Option, ...],
    flags: tuple[str, ...],
    children: list[tuple[str, int]],
    prefix: str,
    *,
    is_group: bool,
) -> list[str]:
    indent = "        "
    lines = [
        "    local opts_done=0 pos=0 i=start word",
        '    local last_opt="" last_count=0 last_max=0',
        "    while (( i < COMP_CWORD )); do",
        '        word="${COMP_WORDS[i]}"',
        "        if (( opts_done )); then",
        "            pos=$((pos + 1))",
        "            i=$((i + 1))",
        "            continue",
        "        fi",
        '        case "$word" in',
    ]
    lines.extend(_option_cases(values, flags, indent=indent))
    lines.extend(
        [
            f"{indent}*)",
            "            if [[ -n $last_opt ]]; then",
            "                last_count=$((last_count + 1))",
            "                if (( last_count >= last_max )); then",
            '                    last_opt=""',
            "                fi",
            "                i=$((i + 1))",
            "                continue",
            "            fi",
        ]
    )
    if children and is_group:
        lines.append('            case "$word" in')
        for child_name, child_id in children:
            lines.extend(
                [
                    f"                {_quote(child_name)})",
                    f'                    {prefix}_cmd_{child_id} "$((i + 1))"',
                    "                    return",
                    "                    ;;",
                ]
            )
        lines.append("            esac")
    lines.extend(
        [
            "            pos=$((pos + 1))",
            "            ;;",
            "        esac",
            "        i=$((i + 1))",
            "    done",
        ]
    )
    return lines


def _inline_cases(values: tuple[_Option, ...], prefix: str) -> list[str]:
    if not values:
        return []
    lines = [
        "    if (( opts_done == 0 )) && [[ $cur == -*=* ]]; then",
        '        case "${cur%%=*}" in',
    ]
    for option in values:
        for option_name in option.names:
            if not option_name.startswith("--"):
                continue
            lines.append(f"            {_quote(option_name)})")
            lines.extend(
                _prefixed_snippet(
                    option.values[0], indent="                ", prefix=prefix
                )
            )
    lines.extend(["        esac", "    fi"])
    return lines


def _pending_value_cases(values: tuple[_Option, ...], prefix: str) -> list[str]:
    if not values:
        return []
    lines = [
        "    if [[ -n $last_opt ]]; then",
        '        case "$last_opt" in',
    ]
    for option in values:
        for option_name in option.names:
            lines.extend(
                _value_case(
                    option_name,
                    option.values,
                    indent="            ",
                    prefix=prefix,
                )
            )
    lines.extend(["        esac", "    fi"])
    return lines


def _offered_names(
    flags: tuple[str, ...], values: tuple[_Option, ...]
) -> tuple[str, ...]:
    return tuple(
        dict.fromkeys(
            (
                *flags,
                *(name for option in values for name in option.names),
            )
        )
    )


def _option_offer(
    flags: tuple[str, ...], values: tuple[_Option, ...], prefix: str
) -> list[str]:
    names = " ".join(_quote(item) for item in _offered_names(flags, values))
    if not names:
        return []
    return [
        "    if (( opts_done == 0 )) && [[ $cur == -* ]]; then",
        f'        {prefix}_offer "$cur" {names}',
        "        return",
        "    fi",
    ]


def _subcommand_offer(
    children: list[tuple[str, int]], prefix: str
) -> list[str]:
    if not children:
        return []
    names = " ".join(_quote(name) for name, _ in children)
    return [
        "    if (( opts_done == 0 && pos == 0 )); then",
        f'        {prefix}_offer "$cur" {names}',
        "    fi",
    ]


def _positional_cases(
    slots: list[_Value],
    variadic: _Value | None,
    variadic_start: int,
    prefix: str,
) -> list[str]:
    indent = "        "
    if variadic is not None:
        snippet = _completion_snippet(variadic, indent=indent, prefix=prefix)
        if not snippet:
            return []
        return [
            f"    if (( pos >= {variadic_start} )); then",
            *snippet,
            "    fi",
        ]
    if not slots:
        return []
    lines = ["    case $pos in"]
    for index, slot in enumerate(slots):
        snippet = _completion_snippet(
            slot, indent=indent + "    ", prefix=prefix
        )
        if not snippet:
            continue
        lines.append(f"        {index})")
        lines.extend(snippet)
        lines.append("            ;;")
    lines.append("    esac")
    return lines


def _function(
    command_id: int,
    command: click.Command,
    children: list[tuple[str, int]],
    prefix: str,
    *,
    is_group: bool,
) -> list[str]:
    name = f"{prefix}_cmd_{command_id}"
    flags, values = _options(command)
    slots, variadic, variadic_start = _positional_slots(command)
    lines = [
        f"{name}() {{",
        "    local start=${1:-1}",
        '    local cur="${COMP_WORDS[COMP_CWORD]}"',
        '    local prev="${COMP_WORDS[COMP_CWORD-1]:-}"',
        "    COMPREPLY=()",
    ]
    lines.extend(
        _parse_body(values, flags, children, prefix, is_group=is_group)
    )
    lines.extend(_inline_cases(values, prefix))
    lines.extend(_pending_value_cases(values, prefix))
    lines.extend(_option_offer(flags, values, prefix))
    lines.extend(_subcommand_offer(children, prefix))
    lines.extend(_positional_cases(slots, variadic, variadic_start, prefix))
    lines.append("}")
    return lines


def _collect(
    group: click.Group,
) -> tuple[dict[int, click.Command], dict[int, list[tuple[str, int]]]]:
    commands: dict[int, click.Command] = {0: group}
    children: dict[int, list[tuple[str, int]]] = {}
    next_id = 1

    def visit(parent_id: int, parent: click.Group) -> None:
        nonlocal next_id
        for child_name, child in parent.commands.items():
            if getattr(child, "hidden", False):
                continue
            child_id = next_id
            next_id += 1
            commands[child_id] = child
            children.setdefault(parent_id, []).append((child_name, child_id))
            if isinstance(child, click.Group):
                visit(child_id, child)

    visit(0, group)
    return commands, children


def _helpers(prefix: str) -> list[str]:
    return [
        f"{prefix}_offer() {{",
        "    local prefix=$1",
        "    shift",
        "    local candidate",
        '    for candidate in "$@"; do',
        '        if [[ $candidate == "$prefix"* ]]; then',
        '            COMPREPLY+=("$candidate")',
        "        fi",
        "    done",
        "}",
        "",
        f"{prefix}_offer_prefixed() {{",
        "    local word=$1",
        "    shift",
        '    local option_prefix="${word%%=*}="',
        '    local value="${word#*=}"',
        "    local candidate",
        "    local reply=()",
        f'    {prefix}_offer "$value" "$@"',
        '    for candidate in "${COMPREPLY[@]}"; do',
        '        reply+=("${option_prefix}${candidate}")',
        "    done",
        '    COMPREPLY=("${reply[@]}")',
        "    compopt -o nospace 2>/dev/null || true",
        "}",
        "",
        f"{prefix}_files() {{",
        "    if declare -F _filedir >/dev/null 2>&1; then",
        "        _filedir",
        "    else",
        '        mapfile -t COMPREPLY < <(compgen -f -- "$cur")',
        "    fi",
        "}",
        "",
        f"{prefix}_dirs() {{",
        "    if declare -F _filedir >/dev/null 2>&1; then",
        "        _filedir -d",
        "    else",
        '        mapfile -t COMPREPLY < <(compgen -d -- "$cur")',
        "    fi",
        "}",
        "",
        f"{prefix}_files_prefixed() {{",
        "    local word=$1",
        '    local option_prefix="${word%%=*}="',
        '    local value="${word#*=}"',
        "    local candidate",
        "    local reply=()",
        "    local cur=$value",
        f"    {prefix}_files",
        '    for candidate in "${COMPREPLY[@]}"; do',
        '        reply+=("${option_prefix}${candidate}")',
        "    done",
        '    COMPREPLY=("${reply[@]}")',
        "    compopt -o nospace 2>/dev/null || true",
        "}",
        "",
        f"{prefix}_dirs_prefixed() {{",
        "    local word=$1",
        '    local option_prefix="${word%%=*}="',
        '    local value="${word#*=}"',
        "    local candidate",
        "    local reply=()",
        "    local cur=$value",
        f"    {prefix}_dirs",
        '    for candidate in "${COMPREPLY[@]}"; do',
        '        reply+=("${option_prefix}${candidate}")',
        "    done",
        '    COMPREPLY=("${reply[@]}")',
        "    compopt -o nospace 2>/dev/null || true",
        "}",
        "",
    ]


def generate_bash(group: click.Group, prog_name: str, version: str) -> str:
    """Return the complete bash completion script.

    Returns:
        The generated script, ending with its ``complete`` registration.

    """
    prefix = f"_{_sanitize(prog_name)}"
    app = f"{prefix}_complete"
    commands, children = _collect(group)
    lines = [
        f"# bash completion for {prog_name} {version}",
        _GENERATED_NOTICE,
        "",
    ]
    lines.extend(_helpers(prefix))
    for command_id, command in commands.items():
        lines.extend(
            _function(
                command_id,
                command,
                children.get(command_id, []),
                prefix,
                is_group=isinstance(command, click.Group),
            )
        )
        lines.append("")
    lines.extend(
        [
            f"{app}() {{",
            f"    {prefix}_cmd_0 1",
            "}",
            "",
            (
                "complete -o nosort -o bashdefault -o default "
                f"-F {app} {_quote(prog_name)}"
            ),
            "",
        ]
    )
    return "\n".join(lines)


def _bash_version() -> tuple[int, int] | None:
    """Return the major and minor version of bash on PATH.

    Returns:
        The version, or ``None`` when bash is missing or unreadable.

    """
    bash = shutil.which("bash")
    if bash is None:
        return None
    try:
        completed = subprocess.run(  # ruff: ignore[subprocess-without-shell-equals-true]
            [
                bash,
                "--norc",
                "-c",
                'printf "%s\\n" "${BASH_VERSINFO[0]}.${BASH_VERSINFO[1]}"',
            ],
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError:
        return None
    match = re.match(r"^(\d+)\.(\d+)", completed.stdout)
    if match is None:
        return None
    return int(match.group(1)), int(match.group(2))


def _warn(message: str) -> None:
    click.echo(f"warning: {message}", err=True)


def completion_path(prog_name: str) -> Path:
    """Return the bash completion script path for PROG_NAME.

    Returns:
        The path under ``BASH_COMPLETION_USER_DIR``, ``XDG_DATA_HOME``, or
        ``~/.local/share``.

    """
    base: Path | None = None
    user_dir = os.environ.get("BASH_COMPLETION_USER_DIR", "")
    for entry in user_dir.split(os.pathsep):
        if entry:
            base = Path(os.path.abspath(Path(entry).expanduser()))
            break
    if base is None:
        data = os.environ.get("XDG_DATA_HOME", "")
        base = (
            Path(os.path.abspath(Path(data).expanduser()))
            if data
            else Path.home() / ".local" / "share"
        )
    return base / "bash-completion" / "completions" / f"{prog_name}.bash"


def _write_atomic(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(
        dir=path.parent, prefix=f".{path.name}.", suffix=".tmp"
    )
    try:
        with os.fdopen(
            descriptor, "w", encoding="utf-8", newline="\n"
        ) as handle:
            handle.write(text)
        Path(temporary).chmod(0o644)
        Path(temporary).replace(path)
    except OSError:
        Path(temporary).unlink(missing_ok=True)
        raise


def install_bash_completion(
    group: click.Group, prog_name: str, version: str
) -> Path:
    """Write the script, print its path, and return the path.

    Returns:
        The path of the written completion script.

    """
    version_info = _bash_version()
    if version_info is None:
        _warn(
            "bash was not found; the completion script was written but "
            "needs bash 4.4 or newer (on macOS, try: brew install bash)"
        )
    elif version_info < BASH_MINIMUM:
        _warn(
            f"bash {version_info[0]}.{version_info[1]} is too old for this "
            "completion script; bash 4.4 or newer is required. On macOS, "
            "install a newer bash (for example: brew install bash)."
        )
    path = completion_path(prog_name)
    _write_atomic(path, generate_bash(group, prog_name, version))
    click.echo(str(path))
    click.echo(
        "To use it in this shell:\n"
        f"  source {path}\n"
        "Automatic loading needs bash-completion 2.18 or newer.",
        err=True,
    )
    return path


def completions_callback(
    ctx: click.Context,
    _param: click.Parameter | None,
    value: bool,  # ruff: ignore[boolean-type-hint-positional-argument]
) -> None:
    """Write bash completions for the current group and exit.

    Raises:
        ClickException: If the current command is not a group.

    """
    if not value or ctx.resilient_parsing:
        return
    command = ctx.command
    if not isinstance(command, click.Group):
        raise click.ClickException("--completions requires a command group")
    install_bash_completion(
        command,
        ctx.info_name or APP_NAME,
        package_version(APP_NAME),
    )
    ctx.exit()


__all__ = [
    "completion_path",
    "completions_callback",
    "generate_bash",
    "install_bash_completion",
]
